function FacetEditor({kind,recordId,data,canEdit,onSave,collapsed=false}:{kind:"excitement"|"participation";recordId:string;data:Data;canEdit:boolean;onSave:(table:string,record:Item,success?:string)=>void;collapsed?:boolean}){const model=data.models.find(m=>m.kind===kind&&m.is_active);const criteria=data.criteria.filter(c=>c.model_id===model?.id).sort((a,b)=>a.position-b.position);const score=criteria.length?calculateScore(criteria.map(c=>({criterion_key:c.criterion_key,weight:c.weight})),data.ratings.filter(r=>r.kind===kind&&(kind==="excitement"?r.robot_id:r.opportunity_id)===recordId)):{score:null,coverage:0,eligible:false,provisional:true};const title=kind==="excitement"?"Meetup excitement":"Participation likelihood";const rows=criteria.map(c=>{const r=data.ratings.find(r=>r.kind===kind&&r.criterion_key===c.criterion_key&&(kind==="excitement"?r.robot_id:r.opportunity_id)===recordId);return <FacetRow key={c.id} criterion={c} rating={r} kind={kind} recordId={recordId} canEdit={canEdit} onSave={onSave} sources={data.sources.filter(s=>r?.source_ids?.includes(s.id))}/>;});if(collapsed)return <ScoreAccordion title={title} summary={<><Score value={score.score} provisional={score.provisional}/><p className="muted">{score.coverage}% score coverage · Ratings use a 1–5 scale</p></>}>{rows}</ScoreAccordion>;return <div className="card"><h2>{title} · <Score value={score.score} provisional={score.provisional}/></h2><p className="muted">{score.coverage}% score coverage · Ratings use a 1–5 scale</p>{rows}</div>;}
