  function dragEnd(event:DragEndEvent){const target=dropTarget;setDropTarget(null);setDraggedId(null);if(!canEdit||!target)return;const vendorId=String(event.active.id);const order=vendorCards.filter(card=>card.stage?.id===target.stageId&&card.id!==vendorId).map(card=>card.id);order.splice(target.index,0,vendorId);const active=vendorCards.find(card=>card.id===vendorId);if(!active||active.stage?.id===target.stageId&&vendorCards.filter(card=>card.stage?.id===target.stageId).map(card=>card.id).join("|")===order.join("|"))return;setScoreSort("manual");onMove(vendorId,target.stageId,order);}
