function MemberSettings({members,onReload,setError}:{members:Item[];onReload:()=>Promise<void>;setError:(x:string)=>void}){
  const [email,setEmail]=useState(""),[firstName,setFirstName]=useState(""),[lastName,setLastName]=useState(""),[role,setRole]=useState("member"),[busy,setBusy]=useState(false),[feedback,setFeedback]=useState<{error:boolean;text:string}|null>(null);
  async function addMember(){if(busy)return;setFeedback(null);setError("");if(!email.trim()||!firstName.trim()||!lastName.trim()){setFeedback({error:true,text:"Enter the email, first name, and last name to add a member."});return;}setBusy(true);try{const response=await fetch("/api/members",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({email:email.trim(),first_name:firstName.trim(),last_name:lastName.trim(),role})});const result=await response.json();if(!response.ok)throw new Error(result.error||"Could not add member");setEmail("");setFirstName("");setLastName("");setFeedback({error:false,text:`Added ${firstName.trim()} ${lastName.trim()} as ${role}.`});await onReload();}catch(error){const message=error instanceof Error?error.message:"Could not add member";setFeedback({error:true,text:message});setError(message);}finally{setBusy(false);}}
  async function updateMember(userId:string,nextRole:string){if(!db)return;const {error}=await db.from("workspace_members").update({role:nextRole as "admin"|"member"|"viewer"}).eq("workspace_id",workspaceId).eq("user_id",userId);if(error)setError(error.message);else await onReload();}
  async function removeMember(userId:string){if(!db||!confirm("Remove this user from the workspace?"))return;const {error}=await db.from("workspace_members").delete().eq("workspace_id",workspaceId).eq("user_id",userId);if(error)setError(error.message);else await onReload();}
  return <div className="card stack"><h2>Workspace members</h2><p className="muted">Add someone before they sign up. Adding them confirms the email administratively; they can sign in later with a magic link. The final admin cannot be removed.</p>{members.map(m=><MemberSettingsRow key={m.user_id} member={m} onUpdateRole={updateMember} onRemove={removeMember} onReload={onReload} setError={setError}/>)}<div className="toolbar"><input className="input" type="email" aria-label="New member email" placeholder="Confirmed account email" value={email} onChange={e=>setEmail(e.target.value)}/><input className="input" aria-label="New member first name" placeholder="First name" value={firstName} onChange={e=>setFirstName(e.target.value)}/><input className="input" aria-label="New member last name" placeholder="Last name" value={lastName} onChange={e=>setLastName(e.target.value)}/><select className="select" aria-label="New member role" value={role} onChange={e=>setRole(e.target.value)}><option value="member">Member</option><option value="viewer">Viewer</option><option value="admin">Admin</option></select><button className="button" disabled={busy} onClick={addMember}>{busy?"Adding…":"Add member"}</button></div>{feedback&&<p className={feedback.error?"notice error":"notice"} role={feedback.error?"alert":"status"}>{feedback.text}</p>}</div>;
}

function MemberSettingsRow({member,onUpdateRole,onRemove,onReload,setError}:{member:Item;onUpdateRole:(userId:string,nextRole:string)=>Promise<void>;onRemove:(userId:string)=>Promise<void>;onReload:()=>Promise<void>;setError:(x:string)=>void}){
  const [editing,setEditing]=useState(false),[firstName,setFirstName]=useState(member.profile?.first_name||""),[lastName,setLastName]=useState(member.profile?.last_name||""),[busy,setBusy]=useState(false);
  useEffect(()=>{setFirstName(member.profile?.first_name||"");setLastName(member.profile?.last_name||"");},[member.profile?.first_name,member.profile?.last_name]);
  async function saveName(){if(!firstName.trim()||!lastName.trim()||busy)return;setBusy(true);try{const response=await fetch("/api/members",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({user_id:member.user_id,first_name:firstName.trim(),last_name:lastName.trim()})});const result=await response.json();if(!response.ok)throw new Error(result.error||"Could not update member name");setEditing(false);await onReload();}catch(error){setError(error instanceof Error?error.message:"Could not update member name");}finally{setBusy(false);}}
  return <div className="stack" style={{borderTop:"1px solid #e7eded",paddingTop:12}}><div className="toolbar"><span className="source"><b>{memberName(member)}</b><br/>{member.email||"Email unavailable"}</span>{editing?<><input className="input" aria-label={`First name for ${memberName(member)}`} autoComplete="given-name" maxLength={100} value={firstName} onChange={e=>setFirstName(e.target.value)}/><input className="input" aria-label={`Last name for ${memberName(member)}`} autoComplete="family-name" maxLength={100} value={lastName} onChange={e=>setLastName(e.target.value)}/><button className="button primary" disabled={!firstName.trim()||!lastName.trim()||busy} onClick={saveName}>{busy?"Saving…":"Save name"}</button><button className="button" disabled={busy} onClick={()=>{setFirstName(member.profile?.first_name||"");setLastName(member.profile?.last_name||"");setEditing(false);}}>Cancel</button></>:<button className="button" onClick={()=>setEditing(true)}>Edit name</button>}<select className="select" aria-label={`Role for ${memberName(member)}`} value={member.role} onChange={e=>void onUpdateRole(member.user_id,e.target.value)}><option value="admin">Admin</option><option value="member">Member</option><option value="viewer">Viewer</option></select><button className="button danger" onClick={()=>void onRemove(member.user_id)}>Remove</button></div></div>;
}

function AssignmentControls({opportunity,members,canEdit,onSave}:{opportunity:Item;members:Item[];canEdit:boolean;onSave:(record:Item)=>void}){
  const collaborators:string[]=opportunity.collaborator_ids||[];
  return <div className="stack"><label className="field">Owner<select className="select" disabled={!canEdit} value={opportunity.owner_id||""} onChange={e=>onSave({id:opportunity.id,owner_id:e.target.value||null})}><option value="">Unassigned</option>{members.map(m=><option key={m.user_id} value={m.user_id}>{memberName(m)}</option>)}</select></label><label className="field">Next action due<input className="input" type="date" disabled={!canEdit} value={opportunity.next_action_date||""} onChange={e=>onSave({id:opportunity.id,next_action_date:e.target.value||null})}/></label><fieldset disabled={!canEdit} style={{border:0,padding:0}}><legend>Collaborators</legend>{members.map(m=><label key={m.user_id} style={{display:"block",fontSize:12,marginTop:6}}><input type="checkbox" checked={collaborators.includes(m.user_id)} onChange={e=>onSave({id:opportunity.id,collaborator_ids:e.target.checked?[...collaborators,m.user_id]:collaborators.filter(id=>id!==m.user_id)})}/> {memberName(m)}</label>)}</fieldset></div>;
}

function GlobalSearch({data,query,onOpen}:{data:Data;query:string;onOpen:(page:Page,id:string)=>void}){
  const needle=query.trim().toLowerCase();
  const includes=(...values:(string|null|undefined)[])=>values.some(value=>value?.toLowerCase().includes(needle));
  const results: {label:string;items:{id:string;title:string;detail:string;page:Page}[]}[]=[
    {label:"Vendors",items:data.vendors.filter(v=>includes(v.name,v.description,data.recordNotes.filter(note=>note.vendor_id===v.id).map(note=>note.body).join(" "),data.locations.filter(l=>l.vendor_id===v.id).map(l=>l.city).join(" "))).map(v=>({id:v.id,title:v.name,detail:[vendorLocation(data.locations,v.id)?.us_state_code||vendorLocation(data.locations,v.id)?.region,vendorLocation(data.locations,v.id)?.iso_country_code].filter(Boolean).join(" · "),page:"vendor"}))},
    {label:"Robots",items:data.robots.filter(r=>includes(r.name,r.description,r.mobility,r.manipulation,r.interaction_capabilities,data.recordNotes.filter(note=>note.robot_id===r.id).map(note=>note.body).join(" "))).map(r=>({id:r.id,title:r.name,detail:data.vendors.find(v=>v.id===r.vendor_id)?.name||"",page:"robot"}))},
    {label:"Contacts",items:data.contacts.filter(c=>includes(c.name,c.job_title,c.department,c.business_email,c.notes)).map(c=>({id:c.vendor_id,title:c.name||c.business_email||"General contact",detail:data.vendors.find(v=>v.id===c.vendor_id)?.name||"",page:"vendor"}))},
    {label:"Locations",items:data.locations.filter(l=>includes(l.city,l.region,l.us_state_code,l.country)).map(l=>({id:l.vendor_id,title:[l.city,l.us_state_code||l.region,l.iso_country_code].filter(Boolean).join(", "),detail:data.vendors.find(v=>v.id===l.vendor_id)?.name||"",page:"vendor"}))},
    {label:"Opportunities",items:data.opportunities.filter(o=>includes(o.next_action,o.outreach_summary,o.outcome)).map(o=>({id:o.id,title:data.robots.find(r=>r.id===o.robot_id)?.name||"Opportunity",detail:o.next_action||o.outreach_summary||"",page:"opportunity"}))},
    {label:"Interactions",items:data.interactions.filter(i=>includes(i.subject,i.summary,i.full_notes,i.outcome)).map(i=>({id:i.opportunity_id,title:i.subject||i.summary||"Interaction",detail:i.full_notes||"",page:"opportunity"}))},
  ];
  return <div className="stack">{!needle?<p className="muted">Enter a term in the search bar above to search this workspace.</p>:results.map(group=><div className="card" key={group.label}><h2>{group.label} · {group.items.length}</h2>{group.items.slice(0,50).map((item,index)=><p key={`${item.id}-${index}`}><a className="link" href="#" onClick={e=>{e.preventDefault();onOpen(item.page,item.id);}}>{item.title}</a> <span className="muted">{item.detail.slice(0,160)}</span></p>)}{group.items.length>50&&<p className="muted">Showing first 50 matches. Narrow the search for more.</p>}</div>)}</div>;
}
